def centroid(n,segs,k,e,visual=False,rho=1):
 A=s.simplify(sum(s.integrate(f-g,(x,lo,hi))for lo,hi,f,g in segs));My=s.simplify(sum(s.integrate(x*(f-g),(x,lo,hi))for lo,hi,f,g in segs));Mx=s.simplify(sum(s.integrate((f*f-g*g)/2,(x,lo,hi))for lo,hi,f,g in segs));cx=s.simplify(My/A);cy=s.simplify(Mx/A);centroids[n]=(segs,cx,cy)
 steps=[]
 if visual:steps.append(('그림에서 도심을 대략 ('+f'{float(cx):.1f},{float(cy):.1f}'+') 부근으로 예상한다.','Visual estimate: near('+f'{float(cx):.1f},{float(cy):.1f}'+').'))
 steps +=[F(r'A=\sum\int(f-g)dx='+tx(A)),F(r'M_y/\rho=\sum\int x(f-g)dx='+tx(My)),F(r'M_x/\rho=\tfrac12\sum\int(f^2-g^2)dx='+tx(Mx)),F(r'\bar x=M_y/(\rho A),\quad\bar y=M_x/(\rho A)')]
 ans=m(r'(\bar x,\bar y)=('+tx(cx)+','+tx(cy)+')')
 if rho!=1:steps.insert(0,F(r'\rho='+str(rho)+r',\quad m='+tx(rho*A)));ans=m('M_x='+tx(rho*Mx)+r',\quad M_y='+tx(rho*My))+ '; '+ans
 add(n,k,e,steps,ans);checks.append({'exercise':n,'area':str(A),'MxOverDensity':str(Mx),'MyOverDensity':str(My),'centroid':[str(cx),str(cy)]})
